   {integrity.issuer_snapshots.length>0&&<div className="tablewrap"><table><thead><tr><th>ETF</th><th>Origin status</th><th>Effective date</th><th>Mapped</th><th>Original issuer file</th></tr></thead><tbody>{integrity.issuer_snapshots.map(a=><tr key={a.fund_symbol}><td><strong>{a.fund_symbol}</strong></td><td>{a.status==='issuer_download_verified'?'Direct issuer download ✓':'Source invalidated'}{a.stale?' · stale':''}</td><td>{a.as_of}</td><td>{pct(a.mapped_weight_pct)} · {a.position_count} rows</td><td><a href={a.source_url} target="_blank" rel="noopener noreferrer">Issuer CSV ↗</a><small>SHA-256 {a.sha256.slice(0,20)}…</small></td></tr>)}</tbody></table></div>}
   {integrity.price_batches.length>0&&<div className="tablewrap"><table><thead><tr><th>Ticker</th><th>Provider</th><th>Price basis</th><th>Observations</th><th>Latest date</th></tr></thead><tbody>{integrity.price_batches.map(b=><tr key={b.symbol}><td>{b.symbol}</td><td>{b.provider}</td><td>Unadjusted close</td><td>{b.observations}</td><td>{b.last_date}{b.stale?' · stale':''}</td></tr>)}</tbody></table></div>}
   {integrity.personal_issuer_import_allowed&&!integrity.demo_only&&!current?.is_demo&&<div className="source-actions"><label>Downloaded issuer file<select aria-label="Issuer fund for personal file" value={issuerSelection} onChange={e=>setIssuerSelection(e.target.value)}>{integrity.issuer_catalog.map(f=><option key={f.fund_symbol} value={f.fund_symbol}>{f.fund_symbol} · {f.issuer}</option>)}</select></label><FileInput label="Import personal issuer CSV (UNVERIFIED)" onUpload={uploadPersonalIssuer}/><p className="fine-note">For private local research only. Download a file manually under the issuer's terms; PortfolioIQ validates its format and date but cannot authenticate its origin. Never redistribute it.</p></div>}
   {integrity.issuer_sync_allowed&&!integrity.demo_only&&!current?.is_demo&&<div className="source-actions"><label>Fund issuer<select aria-label="Issuer fund" value={issuerSelection} onChange={e=>setIssuerSelection(e.target.value)}>{integrity.issuer_catalog.map(f=><option key={f.fund_symbol} value={f.fund_symbol}>{f.fund_symbol} · {f.issuer}</option>)}</select></label><button className="secondary" disabled={busy} onClick={syncIssuer}>Fetch and verify issuer CSV</button><p className="fine-note">Replaces constituent rows for one ETF held in this account, only after parsing and validating an exact HTTPS issuer download.</p></div>}
   {integrity.price_sync_allowed&&!integrity.demo_only&&!current?.is_demo&&current?.kind==='ledger'&&<div className="source-actions"><label>Held security symbol<select aria-label="Held price symbol" value={priceSelection} onChange={e=>setPriceSelection(e.target.value)}><option value="">Choose a held security</option>{dashboard.holdings.filter(h=>h.asset_class!=='Cash Equivalent').map(h=><option key={h.symbol} value={h.symbol}>{h.symbol}</option>)}</select></label><button className="secondary" disabled={busy||!priceSelection} onClick={syncRawPrices}>Replace closes from licensed provider</button><p className="data-warning">Explicit replacement of this security's existing prices. Raw/unadjusted closes only; dividends, splits and fees require matching ledger records.</p></div>}
   <p className="fine-note">{integrity.rights_notice}</p>
