function Kpi({label,value,detail,icon='◈'}:{label:string;value:string;detail:string;icon?:string}){return <div className="kpi"><div className="kpi-label">{label}<span>{icon}</span></div><strong>{value}</strong><small>{detail}</small></div>}
function FileInput({label,onUpload}:{label:string;onUpload:(f:File|null)=>void}){return <label className="upload">⇧ {label}<input type="file" accept=".csv,text/csv" onChange={e=>onUpload(e.target.files?.[0]||null)}/></label>}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);